package com.zero7goat.taz.core.security

import javax.crypto.Cipher
import javax.crypto.SecretKey
import javax.crypto.spec.GCMParameterSpec

/**
 * AES-256-GCM field encryption. Pure JVM code (no Android classes) so it can be unit tested;
 * the key comes from [keyProvider], which in the app is backed by Android Keystore.
 *
 * Stored format, version 1:
 *
 *     [1 byte format version = 1][12 byte random nonce][ciphertext][16 byte GCM tag]
 *
 * The nonce is generated by the cipher for every encryption (never reused or derived).
 * The version byte lets a future format or key change coexist with old data.
 */
class AesGcmFieldCipher(private val keyProvider: () -> SecretKey) : FieldCipher {

    override fun encrypt(plaintext: String, associatedData: String): ByteArray {
        val key = loadKey()
        val plainBytes = plaintext.toByteArray(Charsets.UTF_8)
        try {
            val cipher = Cipher.getInstance(TRANSFORMATION)
            cipher.init(Cipher.ENCRYPT_MODE, key) // the provider picks a fresh random nonce
            cipher.updateAAD(associatedData.toByteArray(Charsets.UTF_8))
            val nonce = cipher.iv
            if (nonce == null || nonce.size != NONCE_BYTES) {
                throw FieldCipherException("Encryption failed")
            }
            val encrypted = cipher.doFinal(plainBytes)
            val blob = ByteArray(1 + NONCE_BYTES + encrypted.size)
            blob[0] = FORMAT_VERSION
            nonce.copyInto(blob, destinationOffset = 1)
            encrypted.copyInto(blob, destinationOffset = 1 + NONCE_BYTES)
            return blob
        } catch (e: FieldCipherException) {
            throw e
        } catch (e: Exception) {
            throw FieldCipherException("Encryption failed")
        } finally {
            plainBytes.fill(0)
        }
    }

    override fun decrypt(blob: ByteArray, associatedData: String): String {
        if (blob.size < MIN_BLOB_BYTES) throw FieldCipherException("Malformed data")
        if (blob[0] != FORMAT_VERSION) throw FieldCipherException("Unsupported data format")
        val key = loadKey()
        val plainBytes = try {
            val cipher = Cipher.getInstance(TRANSFORMATION)
            cipher.init(Cipher.DECRYPT_MODE, key, GCMParameterSpec(TAG_BITS, blob, 1, NONCE_BYTES))
            cipher.updateAAD(associatedData.toByteArray(Charsets.UTF_8))
            cipher.doFinal(blob, 1 + NONCE_BYTES, blob.size - 1 - NONCE_BYTES)
        } catch (e: Exception) {
            // Wrong key, wrong associated data and tampering all end up here.
            throw FieldCipherException("Decryption failed")
        }
        try {
            return String(plainBytes, Charsets.UTF_8)
        } finally {
            plainBytes.fill(0)
        }
    }

    private fun loadKey(): SecretKey =
        try {
            keyProvider()
        } catch (e: Exception) {
            throw FieldCipherException("Encryption key unavailable")
        }

    private companion object {
        const val TRANSFORMATION = "AES/GCM/NoPadding"
        const val FORMAT_VERSION: Byte = 1
        const val NONCE_BYTES = 12
        const val TAG_BITS = 128
        const val MIN_BLOB_BYTES = 1 + NONCE_BYTES + TAG_BITS / 8
    }
}
